export function ConstructGlyph(Name, Size = 16, StrokeWidth = 1.7)
{
    const Wrapper = document.createElement("span");
    Wrapper.className = "action-icon";
    Wrapper.style.cssText = `display:inline-flex;align-items:center;justify-content:center;width:${Size}px;height:${Size}px;flex:none;pointer-events:none;`;
    const Uri = ProjectZeroIconUris[Name];
    if (Uri)
    {
        const Image = document.createElement("img");
        Image.src = Uri;
        Image.width = Size;
        Image.height = Size;
        Image.alt = "";
        Image.draggable = false;
        Image.style.cssText = `width:${Size}px;height:${Size}px;display:block;object-fit:contain;`;
        Wrapper.appendChild(Image);
        return Wrapper;
    }
    const Paths = ProjectZeroActionPaths[Name] || ProjectZeroActionPaths["construct"];
    Wrapper.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="${Size}" height="${Size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${StrokeWidth}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${Paths}</svg>`;
    return Wrapper;
}

